    if event.button() == Qt.RightButton:
        if self._merge_source is not None:
            self.exit_merge_mode()
            event.accept()
            return
        event.ignore()
        return
    if event.button() == Qt.LeftButton:
        if self._merge_source is not None and not isinstance(
